import{_ as a,o as s,c as n,e}from"./app-6be1f847.js";const i={},l=e(`<h3 id="一、配置架构说明" tabindex="-1"><a class="header-anchor" href="#一、配置架构说明" aria-hidden="true">#</a> 一、配置架构说明</h3><p>你有两台服务器：</p><ul><li><strong>服务器A</strong>（NAT网关）： <ul><li>公网IP：可访问互联网（假设为203.0.113.10）</li><li>内网IP：192.168.1.2</li></ul></li><li><strong>服务器B</strong>（客户端）： <ul><li>内网IP：192.168.1.3</li><li>需求：通过服务器A访问互联网</li></ul></li></ul><p>网络拓扑结构：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>[服务器B(192.168.1.3)] &lt;-- 内网 --&gt; [服务器A(192.168.1.2/203.0.113.10)] &lt;-- 公网 --&gt; Internet
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="二、具体配置步骤" tabindex="-1"><a class="header-anchor" href="#二、具体配置步骤" aria-hidden="true">#</a> 二、具体配置步骤</h3><h4 id="_1-配置服务器a-nat网关" tabindex="-1"><a class="header-anchor" href="#_1-配置服务器a-nat网关" aria-hidden="true">#</a> 1. 配置服务器A（NAT网关）</h4><p><strong>1.1 启用IP转发</strong> 让服务器A能够转发数据包：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 临时启用（重启后失效）</span>
<span class="token builtin class-name">echo</span> <span class="token number">1</span> <span class="token operator">&gt;</span> /proc/sys/net/ipv4/ip_forward

<span class="token comment"># 永久启用（推荐）</span>
<span class="token function">sudo</span> <span class="token function">vim</span> /etc/sysctl.conf
<span class="token comment"># 添加或修改这一行</span>
net.ipv4.ip_forward <span class="token operator">=</span> <span class="token number">1</span>

<span class="token comment"># 使配置生效</span>
<span class="token function">sudo</span> <span class="token function">sysctl</span> <span class="token parameter variable">-p</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>1.2 配置iptables NAT规则</strong> 添加SNAT（源地址转换）规则，将来自服务器B的流量伪装成服务器A的公网IP：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 对来自192.168.1.0/24网段的流量，在离开公网接口时进行源地址转换</span>
<span class="token function">sudo</span> iptables <span class="token parameter variable">-t</span> nat <span class="token parameter variable">-A</span> POSTROUTING <span class="token parameter variable">-s</span> <span class="token number">192.168</span>.1.0/24 <span class="token parameter variable">-o</span> eth0 <span class="token parameter variable">-j</span> MASQUERADE

<span class="token comment"># 如果知道公网接口名称（如eth0），也可以明确指定</span>
<span class="token function">sudo</span> iptables <span class="token parameter variable">-t</span> nat <span class="token parameter variable">-A</span> POSTROUTING <span class="token parameter variable">-s</span> <span class="token number">192.168</span>.1.0/24 <span class="token parameter variable">-o</span> eth0 <span class="token parameter variable">-j</span> SNAT --to-source <span class="token number">203.0</span>.113.10
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>1.3 保存iptables规则</strong> 为了让规则在重启后仍然生效，需要保存规则：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 对于CentOS/RHEL系统</span>
<span class="token function">sudo</span> <span class="token function">service</span> iptables save

<span class="token comment"># 对于Debian/Ubuntu系统</span>
<span class="token function">sudo</span> <span class="token function">apt-get</span> <span class="token function">install</span> iptables-persistent
<span class="token function">sudo</span> netfilter-persistent save
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="_2-配置服务器b-客户端" tabindex="-1"><a class="header-anchor" href="#_2-配置服务器b-客户端" aria-hidden="true">#</a> 2. 配置服务器B（客户端）</h4><p><strong>2.1 设置默认网关</strong> 将服务器B的默认网关设置为服务器A的内网IP：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 临时设置（重启后失效）</span>
<span class="token function">sudo</span> route <span class="token function">add</span> default gw <span class="token number">192.168</span>.1.2

<span class="token comment"># 永久设置（根据不同系统）</span>
<span class="token comment"># 对于CentOS/RHEL系统</span>
<span class="token function">sudo</span> <span class="token function">vim</span> /etc/sysconfig/network-scripts/ifcfg-eth0
<span class="token comment"># 添加或修改这一行</span>
<span class="token assign-left variable">GATEWAY</span><span class="token operator">=</span><span class="token number">192.168</span>.1.2

<span class="token comment"># 对于Debian/Ubuntu系统</span>
<span class="token function">sudo</span> <span class="token function">vim</span> /etc/network/interfaces
<span class="token comment"># 添加或修改这一行</span>
gateway <span class="token number">192.168</span>.1.2

<span class="token comment"># 重启网络服务</span>
<span class="token function">sudo</span> systemctl restart network  <span class="token comment"># CentOS/RHEL</span>
<span class="token function">sudo</span> systemctl restart networking  <span class="token comment"># Ubuntu/Debian</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>2.2 配置DNS服务器</strong> 设置DNS服务器，让服务器B能够解析域名：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 编辑DNS配置文件</span>
<span class="token function">sudo</span> <span class="token function">vim</span> /etc/resolv.conf

<span class="token comment"># 添加公共DNS服务器（如Google的DNS）</span>
nameserver <span class="token number">8.8</span>.8.8
nameserver <span class="token number">8.8</span>.4.4
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="三、验证配置" tabindex="-1"><a class="header-anchor" href="#三、验证配置" aria-hidden="true">#</a> 三、验证配置</h3><p><strong>3.1 在服务器B上测试网络连接</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 测试ping公网IP</span>
<span class="token function">ping</span> <span class="token number">8.8</span>.8.8

<span class="token comment"># 测试域名解析</span>
<span class="token function">ping</span> www.baidu.com

<span class="token comment"># 测试访问网页</span>
<span class="token function">curl</span> www.baidu.com
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>3.2 在服务器A上查看NAT规则</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 查看nat表的规则</span>
<span class="token function">sudo</span> iptables <span class="token parameter variable">-t</span> nat <span class="token parameter variable">-L</span> <span class="token parameter variable">-n</span> <span class="token parameter variable">-v</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="四、故障排查" tabindex="-1"><a class="header-anchor" href="#四、故障排查" aria-hidden="true">#</a> 四、故障排查</h3><ol><li><p><strong>检查服务器A的IP转发是否启用</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">cat</span> /proc/sys/net/ipv4/ip_forward
<span class="token comment"># 输出应为1</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>检查服务器A的防火墙是否允许转发</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 允许转发来自内网接口的流量</span>
<span class="token function">sudo</span> iptables <span class="token parameter variable">-A</span> FORWARD <span class="token parameter variable">-i</span> eth1 <span class="token parameter variable">-o</span> eth0 <span class="token parameter variable">-j</span> ACCEPT
<span class="token comment"># 允许转发已建立的连接</span>
<span class="token function">sudo</span> iptables <span class="token parameter variable">-A</span> FORWARD <span class="token parameter variable">-m</span> conntrack <span class="token parameter variable">--ctstate</span> ESTABLISHED,RELATED <span class="token parameter variable">-j</span> ACCEPT
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>检查服务器B的网络配置</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 查看IP地址和网关</span>
<span class="token function">ip</span> addr show
route <span class="token parameter variable">-n</span>

<span class="token comment"># 确保网卡已激活</span>
<span class="token function">sudo</span> <span class="token function">ip</span> <span class="token function">link</span> <span class="token builtin class-name">set</span> eth0 up
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>检查服务器B的DNS配置</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 测试直接使用IP访问网站</span>
<span class="token function">curl</span> <span class="token number">14.215</span>.177.39  <span class="token comment"># 百度的IP地址之一</span>

<span class="token comment"># 如果可以访问，但不能使用域名，则是DNS配置问题</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ol><h3 id="五、高级配置选项" tabindex="-1"><a class="header-anchor" href="#五、高级配置选项" aria-hidden="true">#</a> 五、高级配置选项</h3><p><strong>5.1 指定特定端口转发</strong> 如果你只需要转发特定端口的流量，可以使用更精确的规则：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 只允许转发HTTP/HTTPS流量</span>
<span class="token function">sudo</span> iptables <span class="token parameter variable">-t</span> nat <span class="token parameter variable">-A</span> POSTROUTING <span class="token parameter variable">-s</span> <span class="token number">192.168</span>.1.3 <span class="token parameter variable">-p</span> tcp <span class="token parameter variable">--dport</span> <span class="token number">80</span> <span class="token parameter variable">-o</span> eth0 <span class="token parameter variable">-j</span> MASQUERADE
<span class="token function">sudo</span> iptables <span class="token parameter variable">-t</span> nat <span class="token parameter variable">-A</span> POSTROUTING <span class="token parameter variable">-s</span> <span class="token number">192.168</span>.1.3 <span class="token parameter variable">-p</span> tcp <span class="token parameter variable">--dport</span> <span class="token number">443</span> <span class="token parameter variable">-o</span> eth0 <span class="token parameter variable">-j</span> MASQUERADE
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>5.2 使用更安全的防火墙规则</strong> 可以结合防火墙规则增强安全性：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 允许服务器B访问特定IP段</span>
<span class="token function">sudo</span> iptables <span class="token parameter variable">-A</span> FORWARD <span class="token parameter variable">-s</span> <span class="token number">192.168</span>.1.3 <span class="token parameter variable">-d</span> <span class="token number">8.8</span>.8.0/24 <span class="token parameter variable">-j</span> ACCEPT

<span class="token comment"># 拒绝服务器B访问特定端口</span>
<span class="token function">sudo</span> iptables <span class="token parameter variable">-A</span> FORWARD <span class="token parameter variable">-s</span> <span class="token number">192.168</span>.1.3 <span class="token parameter variable">-p</span> tcp <span class="token parameter variable">--dport</span> <span class="token number">22</span> <span class="token parameter variable">-j</span> REJECT
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>通过以上配置，服务器B就可以通过服务器A访问互联网了。这种配置在企业环境中非常常见，通常用于内部网络共享一个公网IP访问互联网。</p><h2 id="q-aa" tabindex="-1"><a class="header-anchor" href="#q-aa" aria-hidden="true">#</a> Q&amp;AA</h2><h3 id="有公网ip地址的主机-肯定会有两块网卡吗" tabindex="-1"><a class="header-anchor" href="#有公网ip地址的主机-肯定会有两块网卡吗" aria-hidden="true">#</a> 有公网IP地址的主机 肯定会有两块网卡吗?</h3><p>有公网 IP 地址的主机不一定必须有两块网卡，单网卡也可以同时处理公网和内网通信（通过子接口或 VLAN 等技术），但多网卡（一块内网、一块外网）是更常见、更规范的部署方式。 在需要作为网关（如 <code>NAT</code> 服务器）让内网设备访问公网的场景中，通常会使用双网卡，原因是：</p><ul><li>功能隔离：一块网卡（如eth0）连接公网并绑定公网 IP，负责与外部互联网通信；另一块网卡（如eth1）连接内网并绑定内网 IP（如192.168.1.2），负责与内网设备（如服务器 B）通信。</li><li>安全性：物理隔离公网和内网流量，减少直接暴露内网设备的风险，便于通过防火墙规则控制出入站流量。</li><li>网络管理：避免公网 / 内网 IP 冲突，简化路由和 NAT 配置（如之前示例中针对不同网卡的 iptables 规则）。</li></ul><h3 id="这里的-eth1-和-eth0-分别指的是那个机器" tabindex="-1"><a class="header-anchor" href="#这里的-eth1-和-eth0-分别指的是那个机器" aria-hidden="true">#</a> 这里的 eth1 和 eth0 分别指的是那个机器?</h3><p>eth0 和 eth1 是 服务器 A（NAT 网关） 上的两块网卡接口名称，分别对应不同的网络环境，并非指服务器 B 的网卡。eth0：通常代表服务器 A 连接 公网 的网卡接口（即与互联网直接相连的网络接口）.eth1：通常代表服务器 A 连接 内网 的网卡接口（即与服务器 B 所在局域网相连的网络接口）</p><p>实际环境中，网卡接口名称可能不是 eth0/eth1，而是更现代的命名方式（如 enp0s3、ens33 等），具体需通过 <code>ip addr</code> 或 <code>ifconfig</code> 命令查看服务器 A 的网卡名称。 服务器 B 的网卡接口名称不影响服务器 A 的 NAT 配置，只需确保服务器 B 的网关指向服务器 A 的内网 IP（192.168.1.2）即可。</p><blockquote><p>简单来说：eth0 和 eth1 都是服务器 A 上的网卡，分别用于连接公网和内网，与服务器 B 无关。</p></blockquote><h3 id="route-add-default-gw-192-168-1-2-这条命令是什么意思-网关到底起什么作用" tabindex="-1"><a class="header-anchor" href="#route-add-default-gw-192-168-1-2-这条命令是什么意思-网关到底起什么作用" aria-hidden="true">#</a> <code>route add default gw 192.168.1.2</code>，这条命令是什么意思， 网关到底起什么作用</h3><p><code>route add default gw 192.168.1.2</code> 是一条 Linux 系统的路由配置命令，用于设置<strong>默认网关</strong>。下面详细解释其含义和网关的作用：</p><h4 id="命令解析-route-add-default-gw-192-168-1-2" tabindex="-1"><a class="header-anchor" href="#命令解析-route-add-default-gw-192-168-1-2" aria-hidden="true">#</a> 命令解析：<code>route add default gw 192.168.1.2</code></h4><ul><li><strong><code>route add</code></strong>：添加一条路由规则。</li><li><strong><code>default</code></strong>：表示这是一条<strong>默认路由</strong>（即“不知道该往哪发的数据包，都走这条路由”）。</li><li><strong><code>gw 192.168.1.2</code></strong>：<code>gw</code> 是 <code>gateway</code>（网关）的缩写，指定网关的 IP 地址为 <code>192.168.1.2</code>。</li></ul><p><strong>作用</strong>：将 IP 地址为 <code>192.168.1.2</code> 的设备设置为当前主机的<strong>默认出口</strong>，当当前主机需要访问<strong>非本地网络</strong>（如互联网）的目标时，会将数据包发送给这个网关，由网关负责转发。</p><h4 id="网关的核心作用" tabindex="-1"><a class="header-anchor" href="#网关的核心作用" aria-hidden="true">#</a> 网关的核心作用</h4><p>网关（Gateway）是一个网络设备（如路由器、防火墙或服务器），其核心作用是：</p><ol><li><p><strong>跨网络转发数据包</strong></p><ul><li>当主机A（如 <code>192.168.1.3</code>）需要访问主机B（如 <code>8.8.8.8</code>）时，若主机A发现目标IP（<code>8.8.8.8</code>）不在自己的本地网络（<code>192.168.1.0/24</code>）内，就会将数据包发送给<strong>默认网关</strong> （如 <code>192.168.1.2</code>）。</li><li>网关收到数据包后，根据自身的路由表，将数据包转发到下一跳（如公网路由器），最终送达目标。</li></ul></li><li><p><strong>网络协议转换</strong></p><ul><li>网关可以连接不同类型的网络（如局域网和广域网），处理它们之间的协议差异。例如，家庭路由器作为网关，将内网的以太网协议转换为外网的广域网协议（如PPPoE）。</li></ul></li><li><p><strong>NAT（网络地址转换）</strong></p><ul><li>网关常作为 NAT 设备，将内网的私有 IP（如 <code>192.168.1.3</code>）转换为公网 IP（如 <code>203.0.113.10</code>），使多个内网设备共享同一个公网 IP 访问互联网（如之前的服务器A作为NAT网关）。</li></ul></li></ol><h4 id="常见问题" tabindex="-1"><a class="header-anchor" href="#常见问题" aria-hidden="true">#</a> 常见问题</h4><ol><li><p><strong>网关不可达</strong></p><ul><li>若网关（如 <code>192.168.1.2</code>）本身无法访问（如网卡故障、防火墙拦截），则主机无法通过网关访问外部网络。</li><li>解决：检查网关设备是否正常运行，尝试 <code>ping 192.168.1.2</code>。</li></ul></li><li><p><strong>多条默认路由冲突</strong></p><ul><li>若同时配置了多个默认网关，可能导致路由混乱。</li><li>解决：通过 <code>route del default gw &lt;IP&gt;</code> 删除不需要的默认路由。</li></ul></li><li><p><strong>网关未开启IP转发</strong></p><ul><li>若网关设备（如服务器A）未开启 IP 转发（<code>net.ipv4.ip_forward=1</code>），即使数据包到达网关，也无法转发到公网。</li><li>解决：在网关设备上执行 <code>echo 1 &gt; /proc/sys/net/ipv4/ip_forward</code>。</li></ul></li></ol><blockquote><p>总结: 默认网关是主机访问外部网络的“入口”，通过 <code>route add default gw</code> 命令设置后，主机才能将数据包正确发送到网关，进而访问互联网或其他网络。在企业网络、家庭网络中，路由器/防火墙通常就是默认网关设备。</p></blockquote>`,50),t=[l];function r(c,o){return s(),n("div",null,t)}const p=a(i,[["render",r],["__file","/home/runner/work/vuepress_blog/vuepress_blog/docs/.vuepress/.temp/pages/others/computerNetwork/linux_nat.html.vue"]]);export{p as default};
